window.docContents[33].resolve({"/releases/#feat-build-log":{"contents":"The build pipeline previously threaded a bare String → IO Unit error callback through traversal and output generation, and several monads carried their own ad-hoc error loggers.\nThere was no way to emit a warning.\n\nThis release introduces Verso.MonadBuildLog, a uniform logging interface shared across the genres.\nA message carries a Verso.Severity (either Verso.Severity.error or Verso.Severity.warning) and an optional source location.\n\n\n","context":"Writing Documentation in Lean with Verso\u0009Release Notes\u0009Verso 4.31.0","header":"Logging Abstraction","id":"/releases/#feat-build-log"}});